mapper.update:
update wf_collaboration_outbox
set status='PROCESSED',last_http_status=#{httpStatus},last_error_code=null,last_error_summary=null,
    lease_owner=null,lease_until=null,complete_time=current_timestamp(3),revision_no=revision_no+1
where message_id=#{messageId} and status='DELIVERING' and lease_owner=#{leaseOwner}
  and revision_no=#{expectedRevision}

mapper.select:
select message_id from wf_collaboration_outbox
where status in ('PROCESSED','CANCELLED') and complete_time <= #{cutoffTime}
order by complete_time,message_id limit #{limit} for update skip locked

mapper.delete:
delete from wf_collaboration_outbox where message_id in
#{messageId}
  and status in ('PROCESSED','CANCELLED') and complete_time <= #{cutoffTime}
